using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle;

internal sealed class CrossingAnchorLargeExchangeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual crossing label supplies both retained negative gates in the native q-unused three-negative residual, retaining every SMALL occurrence.",
        H("The native crossing label supplies the bridge"),
        Blocks(
            Describe.Lean(DescribeId.Create("native-three-negative-crossing-anchor-exchange"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Circle/CrossingAnchorLargeExchange.actualSource_threeNegative_crossingAnchor_exchange_full"),
                H("Full native exchange with unchanged SMALL inventory"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Use physical labels Fin k for every k>=3 and the centered doubling source s(k,t), for arbitrary natural t. The source cycle has Q=2^(k-2), N=4Q-1 and C=2Q-1. The source action rho includes its physical seam. Set n=rho(p) and x=rho(n). The old word W=A++[x]++T0++[y]++T1++[zpen]++T2++[z]++E is Legal from zero, including Nodup and every natural take. The whole S=T0++T1++T2++E is SMALL, while y,zpen,z are negative LARGE. The prefix A is arbitrary. The actual labels p,n are unused in ALL W, p is positive, n is LARGE, and N<3s(p). Native source geometry derives P=s(p), D=-s(n), r=s(x), with Q<=D<P<r<=C, D=N-2P and r=2P-D.")),
                    Paragraph(Text("The actual crossing label a belongs to S and has aa=s(a)>0. Its actual successor q=rho(a) is unused in ALL W, zpen=rho(q), and qq=s(q)<P. Write ZZ=-s(zpen), Z=-s(z) and h=sum(W). The native region has Q<=Z<=D, C-qq<h<aa-(ZZ-D), and C-P<h<D. No first-crossing, maximality or favorable-path availability assumption is added. The source law first derives qq=2aa because a is positive SMALL; since zpen is negative it then derives ZZ=N-4aa. Consequently delta=ZZ-D=2(P-2aa)>0, so D<ZZ. The upper crossing inequality also implies h<aa-delta<Q.")),
                    Paragraph(Text("Omit an actual largest negative j among [y,zpen,z], breaking a numerical tie by its physical occurrence. The retained physical pair v1,v2 has maximum magnitude M<=ZZ because Z<=D<ZZ. Put c=C-M and tau=C-ZZ=4aa-2Q. Integer crossing bounds C-2aa<h<aa-delta give 3aa>=2Q+delta+1. Hence tau>aa>0, aa+tau>ZZ and 2tau>ZZ. Therefore the ACTUAL label a satisfies 0<aa<=c, M<=aa+c and M<=2c. This is the required bridge resource with no bound on the number or mass of Bad positive SMALL labels.")),
                    Paragraph(Text("Old legality at x gives a0=sum(A)>=0 and a0+r<=C. The inserted pair [p,n] is legal and ends at b=a0+P-D in [0,Q-1]; its intermediate height is a0+P. The exact prospective endpoint is e0=h-s(j)-P. The old blocking bounds and the native budget 2P<=C+Q imply 0<e0<C. The physical suffix partition gives b+sum(S)+s(v1)+s(v2)=e0. Apply the crossing-anchor ordering to ALL S and both retained negatives. It constructs L with (L++[j]).Perm(T0++[y]++T1++[zpen]++T2++[z]++E). The complete new word is literally V=A++[p,n]++L, returning EXACTLY [x,j] and inserting EXACTLY [p,n]. The endpoint need not satisfy e0<=c.")),
                    Paragraph(Text("Every old prefix in A remains literal; both new source gates and every take of L are checked from their actual start. Thus V is Nodup, Legal and InStrip from the ORIGINAL zero, and every natural take, including empty and overlength takes, lies in [0,C]. All old SMALL, including every Bad occurrence, remain. The total physical permutation (V++[x,j]).Perm(W++[p,n]) gives Inventory: exact disjoint used and unused partitions, source balance and complement mass. Only the FULL physical source total zero is used to obtain remainingMass(V)=-e0. No proper source subset is assigned zero charge.")),
                    Paragraph(Text("Both returned and both inserted occurrences are LARGE. Therefore G(V)=G(W), U(V)=U(W), and remainingSmall(V)=remainingSmall(W). The sparse identity is H(V)+3^|s(x)|+3^|s(j)|=H(W)+3^P+3^D. The native expanding path gives 3^P+3^D<3^r, whence strict H(V)<H(W) and strict J=(G,H,U) descent. Since q is positive, qq<P, and p,n are the only inserted labels, q remains unused. The endpoint is exactly e0 in (0,C).")),
                    Paragraph(Text("At a genuine global J minimum, this complete exchange excludes every representative with the stated native configuration, without requiring a chosen representative with few Bad labels. The theorem closes this native q-unused, qq<P, three-negative-LARGE region. It does not prove universal favorable-path availability, the q-in-A or qq>=P branches, other geometries, longer source paths, or suffixes with four or more negative LARGE. Full original-quantifier Circle C3.1 remains open. The result is a deduction in the stated mathematical source theory, without a literature novelty claim."))),
                DescribeRole.Theorem)), []));
}
